cypress_script:
describe('File Upload and Download', () => {
  it('should upload a file successfully', () => {
    cy.visit('https://demoqa.com/upload-download');
    cy.get('#uploadFile').attachFile('exampleFile.txt');
    // Assuming the file gets listed after upload, which is not visible in the inventory
  });

  it('should not change the page on upload when no file is selected', () => {
    cy.visit('https://demoqa.com/upload-download');
    cy.get('#uploadFile').should('exist');
    // Assuming there is some indication that no file was uploaded, which is not visible in the inventory
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('File Upload and Download', () => {
  test('should upload a file successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    const fileInput = await page.locator('#uploadFile');
    await fileInput.setInputFiles('exampleFile.txt');
    // Assuming the file gets listed after upload, which is not visible in the inventory
  });

  test('should not change the page on upload when no file is selected', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    await expect(page.locator('#uploadFile')).toBeVisible();
    // Assuming there is some indication that no file was uploaded, which is not visible in the inventory
  });
});
